import{_t as e,et as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";var i=JSON.parse(`{"title":"一个人开长途真累","description":"","frontmatter":{"title":"一个人开长途真累","date":"2024-09-26T00:00:00.000Z","category":"随笔","tags":["日记"]},"headers":[],"relativePath":"articles/notes/diary/kaichangtu.md","filePath":"articles/notes/diary/kaichangtu.md","articleMeta":{"updated":"2024-09-26","words":298,"minutes":1}}`),a={name:`articles/notes/diary/kaichangtu.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`p`,null,`中秋节脑子一热，开车回趟庄里。总体而言，一个人开中长途（300公里）是真的疲惫。`,-1),t(`p`,null,`很多太空题材的电影，都渲染了太空的恐怖之处——寂静。开长途也有类似的感受，路两边的风景通常是单调的，行道树，或者农田，偶尔会有城郊的建筑；充斥双耳的风噪、与世隔绝的小环境，对时间失去准确感受能力。`,-1),t(`p`,null,`一路上会频繁遇到低速车占用快速道，不得不减速、变道、提速。一到两个龟速车，就可以给高速路带来拥堵。也会遇到表演刀片超车、穿插横跨的杂技选手，希望他们都上足了保险。`,-1),t(`p`,null,`最后，300公里开下来是真的疲惫，也是真的孤独。即使在服务区歇脚、逛超市，人群熙熙攘攘，但对自己而言都是匆忙过客，有一种不真实的热闹感——越是热闹，越是寂静。`,-1)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};